        "scientificDetail": "**新生儿听力筛查**是早期发现先天性听力障碍的关键手段。我国《新生儿听力筛查技术规范》要求所有新生儿在出生后2-5天进行初次筛查，通常采用耳声发射（OAE）或自动听性脑干反应（AABR）进行无创检测。\n\n先天性听力损失的发病率约为1‰-3‰，是常见的出生缺陷之一。若未及时发现，听力障碍将严重影响儿童的语言发育、认知发展和社交能力。早期（6个月内）干预可使患儿的语言发育达到接近正常水平。\n\n**筛查流程：**\n1. 初筛：出生后48小时至出院前完成\n2. 复筛：初筛未通过者，42天内进行复筛\n3. 诊断：复筛仍未通过，3个月内转听力诊断中心",
